'use strict';

const { withQuery } = require('../utils');

/**
 * /v1/orders — create a cart-style order and collect payment for it.
 */
class Orders {
  constructor(client) {
    this.client = client;
  }

  /**
   * List orders.
   * @param {object} [params] Query params (e.g. page, limit, status)
   */
  list(params) {
    return this.client.request('GET', withQuery('/v1/orders', params));
  }

  /**
   * Retrieve a single order by reference.
   * @param {string} reference
   */
  retrieve(reference) {
    return this.client.request('GET', `/v1/orders/${encodeURIComponent(reference)}`);
  }

  /**
   * Create an order.
   * @param {object} params
   * @param {string} params.currency     e.g. "XOF"
   * @param {Array}  params.items        [{ name, sku?, quantity, unit_price }, ...]
   * @param {string} [params.url_success]
   * @param {string} [params.url_error]
   * @param {object} [params.metadata]
   */
  create(params) {
    return this.client.request('POST', '/v1/orders', params);
  }

  /**
   * Cancel/delete an order.
   * @param {string} reference
   */
  cancel(reference) {
    return this.client.request('DELETE', `/v1/orders/${encodeURIComponent(reference)}`);
  }

  /**
   * Pay for an order via Mobile Money.
   * @param {string} reference
   * @param {object} params
   * @param {string} params.operator_code   e.g. "ORANGE_MONEY_CI", "MTN_MONEY_CI", "FLOOZ_MONEY_CI", "WAVE_MONEY_CI"
   * @param {string} params.external_ref    Your own idempotent reference for this payment attempt
   * @param {string} [params.otp]           Required for Orange Money
   * @param {string} [params.payer_phone]
   * @param {string} [params.payer_phone_prefix]
   * @param {string} [params.payer_first_name]
   * @param {string} [params.payer_last_name]
   * @param {string} [params.payer_email]
   * @param {string} [params.customer_id]
   * @param {string} [params.success_url]
   * @param {string} [params.error_url]
   */
  pay(reference, params) {
    return this.client.request('POST', `/v1/orders/${encodeURIComponent(reference)}/pay`, params);
  }
}

module.exports = Orders;
